async function tryUpsertLead(sessionId, messages, ipData) {
  try {
    const userMsgs = messages.filter((m) => m.role === "user");
    if (userMsgs.length < 2) return;
    const allText = messages.map((m) => m.content).join("\n");
    const email = extractEmailFromText(allText);
    if (!email) return;
    const name = userMsgs[0]?.content?.trim();
    if (!name || name.length < 2 || name.length > 80) return;
    const lc = allText.toLowerCase();
    const productType = BOX_KEYWORDS.find((k) => lc.includes(k)) ?? null;
    const quantity = extractQuantity(allText);
    const [existing] = await db.select({ id: quotesTable.id, clarkIp: quotesTable.clarkIp }).from(quotesTable).where(eq(quotesTable.clarkSessionId, sessionId)).limit(1);
    const payload = {
      name,
      email,
      productType: productType || void 0,
      quantity: quantity || void 0,
      message: `Clark AI chat \u2014 ${userMsgs.length} messages exchanged`,
      source: "clark",
      clarkSessionId: sessionId,
      clarkTranscript: JSON.stringify(messages)
    };
    if (ipData?.ip && (!existing || !existing.clarkIp)) {
      payload.clarkIp = ipData.ip;
      payload.clarkCountry = ipData.country;
      payload.clarkCity = ipData.city;
    }
    if (existing) {
      await db.update(quotesTable).set(payload).where(eq(quotesTable.id, existing.id));
    } else {
      const [inserted] = await db.insert(quotesTable).values(payload).returning({ id: quotesTable.id });
      if (inserted?.id) {
        sendLeadNotification({ name, email, productType, quantity, quoteId: inserted.id });
      }
    }
  } catch (e) {
    console.error("Clark lead save error:", e);
  }
}
